from pathlib import Path
import json
REPO=Path(__file__).resolve().parents[2];P=REPO/'04-dashboard';a=json.loads((REPO/'02-data/summary/results.json').read_text(encoding='utf8'))
html='''<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>衣循环 · 电商用户行为分析</title><style>
:root{--ink:#142e3d;--muted:#6b7c86;--teal:#177f75;--blue:#6d8fa5;--amber:#b88448;--line:#dfe6e6;--paper:#f6f8f7}*{box-sizing:border-box}body{margin:0;font:15px/1.5 'Microsoft YaHei',sans-serif;color:var(--ink);background:var(--paper)}header{padding:28px 40px 20px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}h1{font-size:27px;margin:0}header p{margin:5px 0 0;color:var(--muted);font-size:13px}.period{color:var(--muted);text-align:right}.nav{display:flex;gap:30px;padding:0 40px;border-bottom:1px solid var(--line)}button{border:0;background:transparent;font:inherit;color:var(--muted);padding:15px 0;cursor:pointer}button.active{border-bottom:3px solid var(--teal);color:var(--teal);font-weight:bold}main{padding:25px 40px 20px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:25px;border-bottom:1px solid var(--line);padding-bottom:20px}.kpi label{display:block;color:var(--muted);font-size:13px}.kpi b{font-size:34px;display:block;color:var(--teal);font-weight:600;letter-spacing:-.5px}.kpi small{color:var(--muted);font-size:12px}section{display:none}section.active{display:block}h2{font-size:18px;margin:0 0 4px}h3{font-size:15px;margin:16px 0 8px}.base{font-size:12px;color:var(--muted);margin:0 0 14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:22px}.chart{min-width:0}.bar{display:grid;grid-template-columns:112px 1fr 125px;align-items:center;gap:10px;margin:15px 0;font-size:13px}.track{height:24px;background:#e7eeec}.fill{height:24px;background:var(--teal)}.value{text-align:right;font-variant-numeric:tabular-nums}.insight{padding:14px 0;margin-top:18px;color:var(--teal);border-top:1px solid var(--line);font-size:15px}table{border-collapse:collapse;width:100%;font-size:13px;margin-top:12px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:9px 12px}th{color:var(--muted);font-weight:500;background:#edf2f0}td:not(:first-child),th:not(:first-child){text-align:right}.heat{text-align:center!important;font-variant-numeric:tabular-nums}.small{font-size:12px;color:var(--muted)}select{font:inherit;padding:6px 10px;background:white;border:1px solid var(--line);margin:10px 0}svg{width:100%;height:200px}.footer{padding:14px 40px;color:var(--muted);font-size:11px;border-top:1px solid var(--line)}.note{max-width:1050px}.pill{font-size:11px;background:#e7efec;padding:3px 8px;color:var(--teal)}@media(max-width:850px){header{display:block}.grid{grid-template-columns:1fr}.kpis{grid-template-columns:1fr 1fr}.nav,main{padding-left:20px;padding-right:20px}.nav{gap:24px}.bar{grid-template-columns:100px 1fr 100px}.footer{padding:12px 20px}}@media print{section{display:block!important;page-break-before:always}.nav{display:none}body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style>
<header><div><h1>衣循环 <span style="font-weight:400;color:#6b7c86">/ 电商用户行为分析</span></h1><p>旧衣回收小程序中的二手商城方案 · 公开服饰数据验证</p></div><div class="period">2019.10.01 — 2019.10.14 UTC<br><span class="pill">真实公开行为记录 · 非小程序线上日志</span></div></header><div class="nav"><button data-tab="overview" class="active">经营概览</button><button data-tab="funnel">交易漏斗</button><button data-tab="retention">回访留存</button><button data-tab="rfm">RFM 分层</button></div><main>
<section class="active" id="overview"><div class="kpis" id="kpis"></div><div class="grid"><div><h2>服饰用户的交易路径</h2><p class="base">同一用户、会话、商品，按事件时间顺序</p><div id="overview-funnel"></div></div><div><h2>RFM 客群的购买事件金额</h2><p class="base">金额为购买事件价格之和，无数量及退款信息</p><div id="overview-rfm"></div></div></div><div class="grid"><div><h2>每日活跃用户</h2><div id="trend"></div></div><div><h2>留存与价值集中度</h2><table id="quick"></table></div></div><p class="insight" id="overview-insight"></p></section>
<section id="funnel"><h2>浏览 — 购买两步顺序漏斗</h2><p class="base">分析单位=用户×会话×商品。只计浏览后购买的路径，同秒事件允许。服饰子集未观察到加购事件，不推造加购环节。</p><label>服饰子类 <select id="category"><option value="all">全部服饰</option></select></label><div class="grid"><div><div id="detail-funnel"></div></div><div><table id="funnel-table"></table><p class="small">转化率是观察窗口内的路径完成比例，不能解释为促销或页面改版带来的因果变化。</p></div></div><h3>子类路径对比</h3><table id="category-table"></table><p class="insight">迁移至旧衣商城：优先核实商品成色、尺码、卫生处理与运费是否在详情页清楚展示，再开展对照测试。</p></section>
<section id="retention"><h2>按首次观察到的服饰活动日期划分 Cohort</h2><p class="base">留存=同一用户在第N个自然日再次产生任意服饰行为。非注册留存，不完整观察窗口显示“—”。</p><table id="cohorts"></table><p class="insight" id="retention-insight"></p></section>
<section id="rfm"><h2>购买用户的 RFM 分层</h2><p class="base">R=距最近购买天数；F=购买会话数；M=购买事件价格和。快照日2019-10-15 UTC，窗口14天。</p><div class="grid"><div id="rfm-bars"></div><div id="rfm-definitions"></div></div><table id="rfm-table"></table><p class="insight">旧衣商城运营假设：核心价值客群优先测试上新提醒与尺码订阅，近期首购客群测试收货关怀，待唤回客群先识别阻碍再召回。</p></section>
</main><div class="footer"><div class="note">数据：REES46 / Kaggle Multi-category Store，官方2019-Oct文件，筛选 category_code 以 apparel. 开头且时间为10月1—14日。SQL清洗 + Python复核 + HTML/JavaScript交互式BI看板。服饰子集无加购事件，采用两步漏斗。该公开平台并非二手服饰或本小程序，迁移建议尚未上线验证。金额单位保留源价格口径，不代表人民币净收入。</div></div><script>
const A=__DATA__;const fmt=n=>Number(n).toLocaleString('zh-CN');const pc=(n,d)=>d?(100*n/d).toFixed(2)+'%':'—';const money=n=>fmt(Number(n).toFixed(2));
function bars(target,labels,values,den,rate=false){document.querySelector(target).innerHTML=labels.map((x,i)=>`<div class="bar"><span>${x}</span><div class="track"><div class="fill" style="width:${den?values[i]/den*100:0}%"></div></div><span class="value">${rate?pc(values[i],den):fmt(values[i])}</span></div>`).join('')}
let f=A.funnel,r=A.rfm,ret=A.retention_aggregate;document.querySelector('#kpis').innerHTML=[['清洗后行为记录',fmt(A.clean_rows),'服饰类，14天完整窗口'],['活跃用户',fmt(A.users),'匿名user_id去重'],['顺序路径购买率',pc(f.purchases,f.views),'浏览路径完成至购买'],['购买用户',fmt(r.buyers),'仅正价购买事件用户']].map(x=>`<div class="kpi"><label>${x[0]}</label><b>${x[1]}</b><small>${x[2]}</small></div>`).join('');
bars('#overview-funnel',['浏览路径','浏览后购买'],[f.views,f.purchases],f.views);bars('#overview-rfm',r.segments.map(x=>x.segment),r.segments.map(x=>x.value),Math.max(...r.segments.map(x=>x.value)));
document.querySelector('#quick').innerHTML=[['指标','结果'],['D1精确日回访',pc(ret['1'].returned,ret['1'].eligible)],['D7精确日回访',pc(ret['7'].returned,ret['7'].eligible)],['Top20%购买用户金额占比',pc(r.top20_share,1)],['多购买会话用户占比',pc(r.repeat_buyers,r.buyers)]].map((x,i)=>`<tr>${x.map(v=>`<${i?'td':'th'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('');
let ds=A.daily,max=Math.max(...ds.map(x=>x.users)),pts=ds.map((d,i)=>`${35+i*490/(ds.length-1)},${155-d.users/max*120}`).join(' ');document.querySelector('#trend').innerHTML=`<svg viewBox="0 0 560 195"><line x1="35" y1="155" x2="525" y2="155" stroke="#dfe6e6"/><polyline points="${pts}" fill="none" stroke="#177f75" stroke-width="3"/>${ds.map((d,i)=>`<circle cx="${35+i*490/(ds.length-1)}" cy="${155-d.users/max*120}" r="3" fill="#177f75"><title>${d.day}：${fmt(d.users)}人</title></circle>`).join('')}<text x="35" y="182" fill="#6b7c86" font-size="11">10/01</text><text x="480" y="182" fill="#6b7c86" font-size="11">10/14</text><text x="35" y="18" fill="#6b7c86" font-size="11">峰值 ${fmt(max)} 人 / 日</text></svg>`;
const drop1=1-f.purchases/f.views,drop2=0;document.querySelector('#overview-insight').textContent=`浏览至购买路径流失（${pc(Math.max(drop1,drop2),1)}）。子集缺少加购，无法再定位中间环节，建议先验证详情与履约信息。`;
document.querySelector('#category').innerHTML+=A.category_funnel.map(x=>`<option value="${x.category_code}">${x.category_code}</option>`).join('');
function drawFunnel(){let sel=document.querySelector('#category').value,ff=sel==='all'?A.funnel:A.category_funnel.find(x=>x.category_code===sel);bars('#detail-funnel',['浏览路径','浏览后购买'],[ff.views,ff.purchases],ff.views);document.querySelector('#funnel-table').innerHTML=`<tr><th>步骤</th><th>路径数</th><th>上一步转化</th></tr><tr><td>浏览</td><td>${fmt(ff.views)}</td><td>100.00%</td></tr><tr><td>浏览后购买</td><td>${fmt(ff.purchases)}</td><td>${pc(ff.purchases,ff.views)}</td></tr>`}document.querySelector('#category').onchange=drawFunnel;drawFunnel();
document.querySelector('#category-table').innerHTML='<tr><th>服饰子类</th><th>浏览路径</th><th>浏览后购买</th><th>路径购买率</th></tr>'+A.category_funnel.slice(0,8).map(x=>`<tr><td>${x.category_code}</td><td>${fmt(x.views)}</td><td>${fmt(x.purchases)}</td><td>${pc(x.purchases,x.views)}</td></tr>`).join('');
document.querySelector('#cohorts').innerHTML='<tr><th>首次观察日期</th><th>用户数</th><th>D1</th><th>D3</th><th>D7</th></tr>'+A.retention.map(x=>`<tr><td>${x.cohort_day}</td><td>${fmt(x.cohort_users)}</td>${[1,3,7].map(n=>`<td class="heat" style="background:${x['d'+n]===null?'#edf1f0':`rgba(23,127,117,${.06+.75*x['d'+n]/x.cohort_users})`}">${x['d'+n]===null?'—':pc(x['d'+n],x.cohort_users)}</td>`).join('')}</tr>`).join('');document.querySelector('#retention-insight').textContent=`D7：${fmt(ret['7'].returned)} / ${fmt(ret['7'].eligible)} = ${pc(ret['7'].returned,ret['7'].eligible)}。仅纳入10月7日及之前首次观察到的用户，避免将观察不足误判为流失。`;
bars('#rfm-bars',r.segments.map(x=>x.segment),r.segments.map(x=>x.buyers),r.buyers);document.querySelector('#rfm-definitions').innerHTML=`<table><tr><th>分组</th><th>规则</th></tr><tr><td>核心价值</td><td>R≤7，F≥2，M≥P75</td></tr><tr><td>潜力复购</td><td>R≤7，F≥2，其余</td></tr><tr><td>近期首购</td><td>R≤7，F=1</td></tr><tr><td>待唤回</td><td>R>7</td></tr></table><p class="small">M的P75=${money(r.m_quartiles[2])}。短窗口分群，不代表长期客户终身价值。</p>`;document.querySelector('#rfm-table').innerHTML='<tr><th>分组</th><th>用户数</th><th>金额占比</th><th>人均金额</th><th>平均购买会话</th></tr>'+r.segments.map(x=>`<tr><td>${x.segment}</td><td>${fmt(x.buyers)}</td><td>${pc(x.value,r.total_value)}</td><td>${money(x.avg_value)}</td><td>${x.avg_f.toFixed(2)}</td></tr>`).join('');
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button,main section').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')});
</script></html>'''
(P/'index.html').write_text(html.replace('__DATA__',json.dumps(a,ensure_ascii=False)),encoding='utf8')
print('dashboard ready')
